-- Case 2: Buku Kita bookstore (generated, seed 6799)
SET FOREIGN_KEY_CHECKS = 0;
CREATE TABLE MsGenre (GenreID CHAR(5) PRIMARY KEY CHECK (GenreID REGEXP '^GE[0-9]{3}$'), GenreName VARCHAR(50) NOT NULL);
CREATE TABLE MsBook (BookID CHAR(5) PRIMARY KEY CHECK (BookID REGEXP '^BK[0-9]{3}$'), GenreID CHAR(5) NOT NULL, BookTitle VARCHAR(50) NOT NULL, BookPrice FLOAT NOT NULL, BookStock INT NOT NULL, FOREIGN KEY (GenreID) REFERENCES MsGenre(GenreID) ON UPDATE CASCADE ON DELETE CASCADE);
CREATE TABLE MsMember (MemberID CHAR(5) PRIMARY KEY CHECK (MemberID REGEXP '^ME[0-9]{3}$'), MemberName VARCHAR(50) NOT NULL, MemberGender VARCHAR(10) NOT NULL, MemberAddress VARCHAR(50) NOT NULL, MemberEmail VARCHAR(50) NOT NULL, MemberDOB DATE NOT NULL);
CREATE TABLE MsStaff (StaffID CHAR(5) PRIMARY KEY CHECK (StaffID REGEXP '^ST[0-9]{3}$'), StaffName VARCHAR(50) NOT NULL, StaffGender VARCHAR(10) NOT NULL, StaffAddress VARCHAR(50) NOT NULL);
CREATE TABLE SalesHeader (SaleID CHAR(5) PRIMARY KEY CHECK (SaleID REGEXP '^SA[0-9]{3}$'), StaffID CHAR(5) NOT NULL, MemberID CHAR(5) NOT NULL, SaleDate DATE NOT NULL, FOREIGN KEY (StaffID) REFERENCES MsStaff(StaffID) ON UPDATE CASCADE ON DELETE CASCADE, FOREIGN KEY (MemberID) REFERENCES MsMember(MemberID) ON UPDATE CASCADE ON DELETE CASCADE);
CREATE TABLE SalesDetail (SaleID CHAR(5), BookID CHAR(5), Qty INT NOT NULL CHECK (Qty > 0), PRIMARY KEY (SaleID, BookID), FOREIGN KEY (SaleID) REFERENCES SalesHeader(SaleID) ON UPDATE CASCADE ON DELETE CASCADE, FOREIGN KEY (BookID) REFERENCES MsBook(BookID) ON UPDATE CASCADE ON DELETE CASCADE);
